library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity bbq_sqrt_core is generic(WIDTH:positive:=32);port(clk,rst_n,start:in std_logic;radicand:in std_logic_vector(WIDTH-1 downto 0);busy,done:out std_logic;root:out std_logic_vector((WIDTH+1)/2-1 downto 0);remainder:out std_logic_vector(WIDTH-1 downto 0));end;
architecture rtl of bbq_sqrt_core is constant RW:positive:=(WIDTH+1)/2;signal x:unsigned(WIDTH-1 downto 0):=(others=>'0');signal trial,ans:unsigned(RW-1 downto 0):=(others=>'0');signal bitpos:integer range -1 to RW-1:=-1;signal b,d:std_logic:='0';begin root<=std_logic_vector(ans);remainder<=std_logic_vector(x-resize(ans*ans,WIDTH));busy<=b;done<=d;process(clk)variable cand:unsigned(RW-1 downto 0);variable sq:unsigned(2*RW-1 downto 0);begin if rising_edge(clk)then d<='0';if rst_n='0'then x<=(others=>'0');ans<=(others=>'0');bitpos<=-1;b<='0';elsif start='1' and b='0'then x<=unsigned(radicand);ans<=(others=>'0');bitpos<=RW-1;b<='1';elsif b='1'then cand:=ans;cand(bitpos):='1';sq:=cand*cand;if resize(sq,WIDTH)<=x then ans<=cand;end if;if bitpos=0 then bitpos<=-1;b<='0';d<='1';else bitpos<=bitpos-1;end if;end if;end if;end process;end architecture;
